mapper.select:
SELECT 

WHERE r.room_id = #{roomId}
  AND r.reservation_status IN (0, 1)
  AND r.reservation_date = #{date}
  AND r.start_time < #{endTime}
  AND r.end_time > #{startTime}

    AND r.reservation_id != #{excludeReservationId}

SELECT 

WHERE r.user_id = #{userId}
ORDER BY r.created_at DESC

SELECT 

WHERE r.reservation_date BETWEEN #{startDate} AND #{endDate}
ORDER BY mr.room_number, r.reservation_date, r.start_time

SELECT 

WHERE r.reservation_status = #{status,typeHandler=com.meetingroom.typehandler.ReservationStatusTypeHandler}
ORDER BY r.created_at DESC
